values ('c5000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000001', 'MYP5 (Grade 10) Formative Assessment 2 - Criteria A-D', 'Grade 10 · MYP 5 · Mathematics · Formative Assessment 2 (Criteria A–D). Explicit and recursive formulas, arithmetic, quadratic and geometric sequences, and series. Every answer is typed; hints are free and never give the answer.', 'published',
        '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"formative","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","duration_minutes":45,"total_marks":58.0,"source":"assess2-myp5b-criteria"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
