insert into questions (id, organization_id, type, prompt, prompt_doc, explanation, explanation_doc,
                       points, difficulty, topic, subtopic, tags, status, config, created_by,
                       curriculum, curriculum_course, subject_id, review_status, creation_method, class_id)
select ('c5000000-0000-4000-8000' || lpad((100 + (x->>'n')::int)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', x->>'t', x->>'p', x->'d', x->>'e', null,
       (x->>'m')::numeric, x->>'df', x->>'tp', x->>'st',
       array['MYP 5', 'Mathematics', 'formative', 'assess2-criteria'], 'published', x->'cfg', '3c3ed712-f409-4aa1-a645-816418e22ec4',
       'MYP', 'MYP 5 Mathematics', '0a400000-0000-4000-8000-000000000030', 'approved', 'manual', '0a400000-0000-4000-8000-000000000110'
  from jsonb_array_elements('[{"n":1,"t":"numeric","p":"A sequence is defined by the explicit formula $a_n = 4n - 3$. Calculate the 15th term.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sequence is defined by the explicit formula "},{"type":"mathInline","attrs":{"latex":"a_n = 4n - 3"}},{"type":"text","text":". Calculate the 15th term."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"First terms of aₙ = 4n − 3","columns":["n","1","2","3","4"],"rows":[["aₙ","1","5","9","13"]]}}}]},"e":"a₁₅ = 4(15) − 3 = 57.\n\nHint for next time: An explicit formula gives any term directly from n.","m":1,"df":"easy","tp":"explicit and recursive formulas","st":"explicit formula","cfg":{"source":"assess2-myp5b-criteria","question_number":1,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"An explicit formula gives any term directly from n.","assessment_style":"assess2_criteria_typed","hints":["An explicit formula gives any term directly from n.","Substitute n = 15 into the formula."],"numeric_answer":57,"tolerance":0}},{"n":2,"t":"numeric","p":"A sequence is defined recursively: $a_1 = 5$, $a_{n+1} = a_n + 6$. The first terms are shown. Calculate the 6th term.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sequence is defined recursively: "},{"type":"mathInline","attrs":{"latex":"a_1 = 5"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"a_{n+1} = a_n + 6"}},{"type":"text","text":". The first terms are shown. Calculate the 6th term."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Recursive sequence: add 6 each time","columns":["n","1","2","3","4","5","6"],"rows":[["aₙ","5","11","17","23","29","?"]]}}}]},"e":"Terms: 5, 11, 17, 23, 29, 35 — a₆ = 35.\n\nHint for next time: A recursive rule builds each term from the previous one.","m":1,"df":"easy","tp":"explicit and recursive formulas","st":"recursive formula","cfg":{"source":"assess2-myp5b-criteria","question_number":2,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"A recursive rule builds each term from the previous one.","assessment_style":"assess2_criteria_typed","hints":["A recursive rule builds each term from the previous one.","Keep adding 6, one step at a time, until you reach the 6th term."],"numeric_answer":35,"tolerance":0}},{"n":3,"t":"assess_parts","p":"An arithmetic sequence has first term 7 and common difference 4. The graph shows its first four terms. Calculate the 20th term.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An arithmetic sequence has first term 7 and common difference 4. The graph shows its first four terms. Calculate the 20th term."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Arithmetic sequence (a = 7, d = 4)","xLabel":"Term number n","yLabel":"Term aₙ","xMin":0,"xMax":5,"yMin":0,"yMax":25,"points":[[1,7],[2,11],[3,15],[4,19]],"joinPoints":false}}}]},"e":"a₂₀ = 7 + 19 × 4 = 83.\n\nHint for next time: Compare consecutive terms on the graph.","m":2,"df":"medium","tp":"arithmetic sequences","st":"arithmetic nth term","cfg":{"source":"assess2-myp5b-criteria","question_number":3,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"Compare consecutive terms on the graph.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the common difference.","kind":"numeric","points":1,"hints":["Compare consecutive terms on the graph.","Subtract one term from the next."],"strand":"A(i)","answer":4,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the 20th term.","kind":"numeric","points":1,"hints":["Use aₙ = a + (n − 1)d with the values given.","Start from 7 and add the difference 19 times."],"strand":"A(iii)","answer":83,"tolerance":0}]}},{"n":4,"t":"numeric","p":"Find the sum of the first 12 terms of the arithmetic series 3 + 7 + 11 + 15 + …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the sum of the first 12 terms of the arithmetic series 3 + 7 + 11 + 15 + …"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Arithmetic series","columns":["Term","1st","2nd","3rd","4th"],"rows":[["Value","3","7","11","15"]]}}}]},"e":"a = 3, d = 4. S₁₂ = (12/2)(2×3 + 11×4) = 6 × 50 = 300.\n\nHint for next time: A series sum uses the first term, the difference and the number of terms.","m":1,"df":"medium","tp":"arithmetic series","st":"arithmetic series sum","cfg":{"source":"assess2-myp5b-criteria","question_number":4,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"A series sum uses the first term, the difference and the number of terms.","assessment_style":"assess2_criteria_typed","hints":["A series sum uses the first term, the difference and the number of terms.","Apply Sₙ = (n/2)(2a + (n − 1)d) with n = 12."],"numeric_answer":300,"tolerance":0}},{"n":5,"t":"assess_parts","p":"A quadratic sequence has nth term $a_n = n^2 + 2n$. Calculate the 9th term and the difference between the 9th and 8th terms.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A quadratic sequence has nth term "},{"type":"mathInline","attrs":{"latex":"a_n = n^2 + 2n"}},{"type":"text","text":". Calculate the 9th term and the difference between the 9th and 8th terms."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"aₙ = n² + 2n","columns":["n","1","2","3","4"],"rows":[["aₙ","3","8","15","24"]]}}}]},"e":"a₉ = 81 + 18 = 99; a₈ = 64 + 16 = 80; difference = 19.\n\nHint for next time: Substitute n = 9 into both parts of the formula.","m":2,"df":"hard","tp":"quadratic sequences","st":"quadratic nth term","cfg":{"source":"assess2-myp5b-criteria","question_number":5,"myp_criterion":"A","strand":"A(ii)","next_time_hint":"Substitute n = 9 into both parts of the formula.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate the 9th term.","kind":"numeric","points":1,"hints":["Substitute n = 9 into both parts of the formula.","Square 9, add double 9."],"strand":"A(iii)","answer":99,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate a₉ − a₈.","kind":"numeric","points":1,"hints":["You need the 8th term as well.","Evaluate the formula at n = 8, then subtract from your (a) answer."],"strand":"A(ii)","answer":19,"tolerance":0}]}},{"n":6,"t":"numeric","p":"A geometric sequence has first term 5 and common ratio 3. Calculate the 6th term.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A geometric sequence has first term 5 and common ratio 3. Calculate the 6th term."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Geometric sequence (a = 5, r = 3)","columns":["n","1","2","3","4"],"rows":[["aₙ","5","15","45","135"]]}}}]},"e":"a₆ = 5 × 3⁵ = 5 × 243 = 1215.\n\nHint for next time: Each term is the previous one multiplied by the ratio.","m":1,"df":"medium","tp":"geometric sequences","st":"geometric nth term","cfg":{"source":"assess2-myp5b-criteria","question_number":6,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"Each term is the previous one multiplied by the ratio.","assessment_style":"assess2_criteria_typed","hints":["Each term is the previous one multiplied by the ratio.","Use aₙ = a × rⁿ⁻¹ with n = 6 — count the multiplications carefully."],"numeric_answer":1215,"tolerance":0}},{"n":7,"t":"numeric","p":"Find the sum of the first 8 terms of the geometric series 3 + 6 + 12 + 24 + …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the sum of the first 8 terms of the geometric series 3 + 6 + 12 + 24 + …"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Geometric series","columns":["Term","1st","2nd","3rd","4th"],"rows":[["Value","3","6","12","24"]]}}}]},"e":"a = 3, r = 2. S₈ = 3(2⁸ − 1)/(2 − 1) = 3 × 255 = 765.\n\nHint for next time: Identify the ratio first by dividing consecutive terms.","m":1,"df":"hard","tp":"geometric series","st":"geometric series sum","cfg":{"source":"assess2-myp5b-criteria","question_number":7,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"Identify the ratio first by dividing consecutive terms.","assessment_style":"assess2_criteria_typed","hints":["Identify the ratio first by dividing consecutive terms.","Apply Sₙ = a(rⁿ − 1)/(r − 1) with n = 8."],"numeric_answer":765,"tolerance":0}},{"n":8,"t":"assess_parts","p":"Investigation: matchstick houses are built in a row. The figures show houses 1, 2 and 3. Investigate the number of matchsticks.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: matchstick houses are built in a row. The figures show houses 1, 2 and 3. Investigate the number of matchsticks."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"Matchstick houses","patterns":[{"label":"House 1","squares":1,"dots":5},{"label":"House 2","squares":2,"dots":9},{"label":"House 3","squares":3,"dots":13}]}}}]},"e":"Matches: 5, 9, 13, … differences of 4. House 4 needs 17; rule M = 4n + 1; house 25 needs 4 × 25 + 1 = 101.\n\nHint for next time: Look at how the count grows from house to house.","m":3.0,"df":"medium","tp":"quadratic sequences","st":"linear pattern: matchstick houses","cfg":{"source":"assess2-myp5b-criteria","question_number":8,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Look at how the count grows from house to house.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many matchsticks does house 4 need?","kind":"numeric","points":0.5,"hints":["Look at how the count grows from house to house.","Continue the pattern by its constant difference."],"strand":"B(i)","answer":17,"tolerance":0},{"id":"b","label":"(b)","prompt":"Complete the rule check: how many matchsticks does house 5 need?","kind":"numeric","points":0.5,"hints":["Apply the same growth once more.","Add the constant difference to your house-4 value."],"strand":"B(i)","answer":21,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for M matchsticks in house n. Type like M=4n+1.","kind":"expression","points":1,"hints":["The multiplier of n is the constant difference.","Combine the difference with the starting adjustment."],"strand":"B(ii)","accepted":["M=4n+1","4n+1"]},{"id":"d","label":"(d)","prompt":"Verify your rule: calculate the matchsticks for house 25.","kind":"numeric","points":1,"hints":["Substitute n = 25 into your rule.","Multiply 25 by the difference and add the constant."],"strand":"B(iii)","answer":101,"tolerance":0}]}},{"n":9,"t":"assess_parts","p":"Investigation: square tiles are arranged in growing squares. The table shows the total number of tiles in each figure. Investigate the pattern.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: square tiles are arranged in growing squares. The table shows the total number of tiles in each figure. Investigate the pattern."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"Square tile figures","patterns":[{"label":"Figure 1","squares":1},{"label":"Figure 2","squares":4},{"label":"Figure 3","squares":9},{"label":"Figure 4","squares":16}]}}}]},"e":"Totals: 1, 4, 9, 16 — these are square numbers. Figure 5 has 25 tiles; rule T = n²; figure 12 has 144 tiles.\n\nHint for next time: Look at the shape of the numbers 1, 4, 9, 16.","m":2.5,"df":"hard","tp":"quadratic sequences","st":"quadratic pattern: squares","cfg":{"source":"assess2-myp5b-criteria","question_number":9,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Look at the shape of the numbers 1, 4, 9, 16.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many tiles are in figure 5?","kind":"numeric","points":0.5,"hints":["Look at the shape of the numbers 1, 4, 9, 16.","Each total is the figure number multiplied by itself."],"strand":"B(i)","answer":25,"tolerance":0},{"id":"b","label":"(b)","prompt":"What is the first difference between consecutive totals at figure 4 to 5? (a₅ − a₄)","kind":"numeric","points":0.5,"hints":["Subtract the figure-4 total from the figure-5 total.","Use your answer to (a) minus 16."],"strand":"B(i)","answer":9,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for T tiles in figure n. Type like T=n^2.","kind":"expression","points":1,"hints":["The totals are a very familiar family of numbers.","Express the total using the figure number squared."],"strand":"B(ii)","accepted":["T=n^2","n^2","T=n²"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many tiles are in figure 12?","kind":"numeric","points":0.5,"hints":["Substitute n = 12 into your rule.","Square the figure number."],"strand":"B(iii)","answer":144,"tolerance":0}]}},{"n":10,"t":"assess_parts","p":"Investigation: the table shows the number of dots in triangular arrangements. Investigate the totals.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: the table shows the number of dots in triangular arrangements. Investigate the totals."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Triangular dot arrangements","columns":["Stage n","1","2","3","4","5","6"],"rows":[["Total dots","1","3","6","10","15","?"]]}}}]},"e":"Totals: 1, 3, 6, 10, 15 — triangular numbers, differences 2, 3, 4, 5. Next total 21; rule T = n(n + 1)/2; stage 10 gives 10 × 11/2 = 55.\n\nHint for next time: Watch how the differences themselves grow.","m":3.0,"df":"hard","tp":"quadratic sequences","st":"quadratic pattern: triangular numbers","cfg":{"source":"assess2-myp5b-criteria","question_number":10,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Watch how the differences themselves grow.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the total number of dots at stage 6.","kind":"numeric","points":0.5,"hints":["Watch how the differences themselves grow.","The increases are 2, 3, 4, 5, … continue them."],"strand":"B(i)","answer":21,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write down the second difference of the totals.","kind":"numeric","points":0.5,"hints":["First find the differences, then difference those.","Differences grow by the same amount each time — find it."],"strand":"B(i)","answer":1,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for T dots at stage n. Type like T=n(n+1)/2.","kind":"expression","points":1,"hints":["Each total is half of a product of two consecutive numbers.","Multiply n by the next whole number and halve."],"strand":"B(ii)","accepted":["T=n(n+1)/2","n(n+1)/2","T=(n^2+n)/2","0.5n^2+0.5n"]},{"id":"d","label":"(d)","prompt":"Verify your rule at stage 10: type the total.","kind":"numeric","points":1,"hints":["Substitute n = 10 into your rule.","Multiply 10 by 11 and halve."],"strand":"B(iii)","answer":55,"tolerance":0}]}},{"n":11,"t":"assess_parts","p":"Investigation: a sheet of paper is folded in half repeatedly. The table shows the number of layers after each fold. Investigate the growth.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: a sheet of paper is folded in half repeatedly. The table shows the number of layers after each fold. Investigate the growth."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Paper folding investigation","columns":["Folds n","1","2","3","4","5"],"rows":[["Layers","2","4","8","16","?"]]}}}]},"e":"Layers: 2, 4, 8, 16 — doubling. After 5 folds: 32; rule L = 2ⁿ; after 10 folds: 1024 layers.\n\nHint for next time: Each fold doubles the layers.","m":2.5,"df":"medium","tp":"geometric sequences","st":"geometric pattern: folding","cfg":{"source":"assess2-myp5b-criteria","question_number":11,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Each fold doubles the layers.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many layers are there after 5 folds?","kind":"numeric","points":0.5,"hints":["Each fold doubles the layers.","Multiply the 4-fold value by the growth factor."],"strand":"B(i)","answer":32,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many layers are there after 6 folds?","kind":"numeric","points":0.5,"hints":["Double once more.","Multiply your 5-fold value by the same factor."],"strand":"B(i)","answer":64,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for L layers after n folds. Type like L=2^n.","kind":"expression","points":1,"hints":["Repeated doubling is a power.","Write the layer count as 2 to the power of folds."],"strand":"B(ii)","accepted":["L=2^n","2^n"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many layers after 10 folds?","kind":"numeric","points":0.5,"hints":["Substitute n = 10 into your rule.","Calculate 2 to the power 10."],"strand":"B(iii)","answer":1024,"tolerance":0}]}},{"n":12,"t":"assess_parts","p":"Investigation: seats are arranged in rows at an outdoor cinema. Each row has 4 more seats than the row before. Investigate the seating.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: seats are arranged in rows at an outdoor cinema. Each row has 4 more seats than the row before. Investigate the seating."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Cinema seating investigation","columns":["Row n","1","2","3","4","5"],"rows":[["Seats","12","16","20","24","?"]]}}}]},"e":"Rows: 12, 16, 20, 24, … Row 5 has 28 seats; rule S = 4n + 8; row 15 has 4 × 15 + 8 = 68 seats.\n\nHint for next time: The rows grow by a constant amount.","m":3.0,"df":"medium","tp":"arithmetic sequences","st":"linear pattern: seating rows","cfg":{"source":"assess2-myp5b-criteria","question_number":12,"myp_criterion":"B","strand":"B(i)","next_time_hint":"The rows grow by a constant amount.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many seats are in row 5?","kind":"numeric","points":0.5,"hints":["The rows grow by a constant amount.","Continue the sequence by its difference."],"strand":"B(i)","answer":28,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many seats are in row 6?","kind":"numeric","points":0.5,"hints":["Add the constant difference again.","Extend your row-5 value by the same step."],"strand":"B(i)","answer":32,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for S seats in row n. Type like S=4n+8.","kind":"expression","points":1,"hints":["Use the common difference as the multiplier of n.","Combine 4n with the constant that fits row 1."],"strand":"B(ii)","accepted":["S=4n+8","4n+8"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many seats are in row 15?","kind":"numeric","points":1,"hints":["Substitute n = 15 into your rule.","Multiply 15 by the difference and add the constant."],"strand":"B(iii)","answer":68,"tolerance":0}]}},{"n":13,"t":"assess_parts","p":"Investigation: a staircase is built from blocks. The diagram shows the number of blocks in each staircase. Investigate the totals.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: a staircase is built from blocks. The diagram shows the number of blocks in each staircase. Investigate the totals."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"Block staircases","patterns":[{"label":"Stair 1","squares":1},{"label":"Stair 2","squares":3},{"label":"Stair 3","squares":6},{"label":"Stair 4","squares":10}]}}}]},"e":"Blocks: 1, 3, 6, 10 — the same triangular growth: differences increase by 1. Staircase 5 needs 15 blocks; rule B = n(n + 1)/2; staircase 8 needs 36.\n\nHint for next time: Look at the differences: 2, 3, 4, …","m":3.0,"df":"hard","tp":"explicit and recursive formulas","st":"staircase recursive pattern","cfg":{"source":"assess2-myp5b-criteria","question_number":13,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Look at the differences: 2, 3, 4, …","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many blocks does staircase 5 need?","kind":"numeric","points":0.5,"hints":["Look at the differences: 2, 3, 4, …","Add the next difference to the staircase-4 total."],"strand":"B(i)","answer":15,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many blocks does staircase 6 need?","kind":"numeric","points":0.5,"hints":["The differences keep growing by 1.","Add the next difference to your staircase-5 total."],"strand":"B(i)","answer":21,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for B blocks in staircase n. Type like B=n(n+1)/2.","kind":"expression","points":1,"hints":["These totals are triangular numbers.","Multiply n by the next integer and halve."],"strand":"B(ii)","accepted":["B=n(n+1)/2","n(n+1)/2","B=(n^2+n)/2"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many blocks does staircase 8 need?","kind":"numeric","points":1,"hints":["Substitute n = 8 into your rule.","Multiply 8 by 9 and halve."],"strand":"B(iii)","answer":36,"tolerance":0}]}},{"n":14,"t":"assess_parts","p":"Investigation: a rumour spreads so that each day, the number of new people who hear it triples. The table shows new hearers per day. Investigate the growth.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: a rumour spreads so that each day, the number of new people who hear it triples. The table shows new hearers per day. Investigate the growth."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Rumour spread investigation","columns":["Day n","1","2","3","4","5"],"rows":[["New hearers","2","6","18","54","?"]]}}}]},"e":"New hearers: 2, 6, 18, 54 — tripling. Day 5: 162; rule N = 2 × 3ⁿ⁻¹; day 7: 2 × 3⁶ = 1458.\n\nHint for next time: Find the multiplying factor between days.","m":3.0,"df":"hard","tp":"geometric sequences","st":"geometric pattern: spread","cfg":{"source":"assess2-myp5b-criteria","question_number":14,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Find the multiplying factor between days.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many new people hear the rumour on day 5?","kind":"numeric","points":0.5,"hints":["Find the multiplying factor between days.","Multiply the day-4 value by the common ratio."],"strand":"B(i)","answer":162,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write down the common ratio.","kind":"numeric","points":0.5,"hints":["Divide one day''s value by the previous day''s.","Compare consecutive values in the table."],"strand":"B(i)","answer":3,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for N new hearers on day n. Type like N=2(3)^(n-1).","kind":"expression","points":1,"hints":["Start from the day-1 value and apply the ratio repeatedly.","Write the first term times the ratio to the power (n − 1)."],"strand":"B(ii)","accepted":["N=2(3)^(n-1)","2*3^(n-1)","N=2×3^(n-1)","2(3)^(n-1)"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many new hearers on day 7?","kind":"numeric","points":1,"hints":["Substitute n = 7 into your rule.","Multiply the first term by the ratio to the power 6."],"strand":"B(iii)","answer":1458,"tolerance":0}]}},{"n":15,"t":"assess_parts","p":"Investigation: tables are pushed together in a café and the number of seats around them is recorded. Investigate the seating pattern.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: tables are pushed together in a café and the number of seats around them is recorded. Investigate the seating pattern."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Café tables investigation","columns":["Tables n","1","2","3","4","5"],"rows":[["Seats","6","10","14","18","?"]]}}}]},"e":"Seats: 6, 10, 14, 18 for 1–4 tables: each extra table adds 4 seats (two per long side), while the two end seats are constant. Rule S = 4n + 2; 12 tables seat 4 × 12 + 2 = 50.\n\nHint for next time: Find the constant increase per extra table.","m":3.0,"df":"hard","tp":"quadratic sequences","st":"linear pattern: café tables","cfg":{"source":"assess2-myp5b-criteria","question_number":15,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Find the constant increase per extra table.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many seats are there with 5 tables?","kind":"numeric","points":0.5,"hints":["Find the constant increase per extra table.","Continue the pattern by its difference."],"strand":"B(i)","answer":22,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many seats are there with 6 tables?","kind":"numeric","points":0.5,"hints":["Add the same increase again.","Extend your 5-table value by the step."],"strand":"B(i)","answer":26,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the general rule for S seats with n tables. Type like S=4n+2.","kind":"expression","points":1,"hints":["Two seats are always at the ends; the sides grow with n.","Use the difference as multiplier and fit the constant to n = 1."],"strand":"B(ii)","accepted":["S=4n+2","4n+2"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many seats with 12 tables?","kind":"numeric","points":1,"hints":["Substitute n = 12 into your rule.","Multiply 12 by the difference and add the constant."],"strand":"B(iii)","answer":50,"tolerance":0}]}},{"n":16,"t":"assess_parts","p":"Investigation: a training app increases a runner''s daily distance. The graph shows the distance for the first five days. Investigate the plan.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigation: a training app increases a runner''s daily distance. The graph shows the distance for the first five days. Investigate the plan."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Training plan distances","xLabel":"Day n","yLabel":"Distance (km)","xMin":0,"xMax":6,"yMin":0,"yMax":14,"points":[[1,3],[2,5],[3,7],[4,9],[5,11]],"joinPoints":false}}}]},"e":"Distances: 3, 5, 7, 9, 11 km — increasing by 2 each day. Day 6: 13 km; rule D = 2n + 1; day 20: 41 km.\n\nHint for next time: Read the growth between the plotted points.","m":3.0,"df":"medium","tp":"arithmetic sequences","st":"linear pattern from a graph","cfg":{"source":"assess2-myp5b-criteria","question_number":16,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Read the growth between the plotted points.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What distance is run on day 6?","kind":"numeric","points":0.5,"hints":["Read the growth between the plotted points.","Continue the pattern by its constant step."],"strand":"B(i)","answer":13,"tolerance":0,"unit":"km"},{"id":"b","label":"(b)","prompt":"What distance is run on day 7?","kind":"numeric","points":0.5,"hints":["Apply the same daily increase.","Add the step to your day-6 distance."],"strand":"B(i)","answer":15,"tolerance":0,"unit":"km"},{"id":"c","label":"(c)","prompt":"Write the general rule for D km on day n. Type like D=2n+1.","kind":"expression","points":1,"hints":["The multiplier of n is the daily increase.","Fit the constant so that n = 1 gives 3."],"strand":"B(ii)","accepted":["D=2n+1","2n+1"]},{"id":"d","label":"(d)","prompt":"Verify your rule: what distance is run on day 20?","kind":"numeric","points":1,"hints":["Substitute n = 20 into your rule.","Multiply 20 by the step and add the constant."],"strand":"B(iii)","answer":41,"tolerance":0,"unit":"km"}]}},{"n":17,"t":"assess_parts","p":"Move between representations: a sequence is given by the recursive rule $a_1 = 10$, $a_{n+1} = a_n - 3$. The graph shows the first terms. Write the explicit formula and use it.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Move between representations: a sequence is given by the recursive rule "},{"type":"mathInline","attrs":{"latex":"a_1 = 10"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"a_{n+1} = a_n - 3"}},{"type":"text","text":". The graph shows the first terms. Write the explicit formula and use it."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Recursive sequence graphed","xLabel":"Term number n","yLabel":"Term aₙ","xMin":0,"xMax":6,"yMin":-4,"yMax":12,"points":[[1,10],[2,7],[3,4],[4,1],[5,-2]],"joinPoints":false}}}]},"e":"Terms: 10, 7, 4, 1, −2 — arithmetic with a = 10, d = −3. Explicit: aₙ = 13 − 3n. a₁₂ = 13 − 36 = −23.\n\nHint for next time: Convert the repeated subtraction into a formula in n.","m":2,"df":"medium","tp":"explicit and recursive formulas","st":"recursive to explicit","cfg":{"source":"assess2-myp5b-criteria","question_number":17,"myp_criterion":"C","strand":"C(iii)","next_time_hint":"Convert the repeated subtraction into a formula in n.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write the explicit formula. Type like a_n=13-3n.","kind":"expression","points":1,"hints":["Convert the repeated subtraction into a formula in n.","Use a + (n − 1)d and simplify."],"strand":"C(iii)","accepted":["a_n=13-3n","13-3n","a_n=-3n+13"]},{"id":"b","label":"(b)","prompt":"Use your formula to calculate the 12th term.","kind":"numeric","points":1,"hints":["Substitute n = 12 into your explicit formula.","Multiply 12 by the difference and combine with the constant."],"strand":"C(iii)","answer":-23,"tolerance":0}]}},{"n":18,"t":"assess_parts","p":"Find the error. A student writes: \"For 2, 6, 18, 54, …, the 5th term is 54 + 36 = 90 because the differences are 4, 12, 36.\" Type the correct 5th term.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the error. A student writes: \"For 2, 6, 18, 54, …, the 5th term is 54 + 36 = 90 because the differences are 4, 12, 36.\" Type the correct 5th term."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Student''s sequence","columns":["n","1","2","3","4","5"],"rows":[["Term","2","6","18","54","?"]]}}}]},"e":"The sequence is geometric with ratio 3, not arithmetic: 5th term = 54 × 3 = 162. The differences themselves grow by ×3.\n\nHint for next time: Check ratios, not just differences, for this sequence.","m":2,"df":"hard","tp":"geometric sequences","st":"find the error: geometric","cfg":{"source":"assess2-myp5b-criteria","question_number":18,"myp_criterion":"C","strand":"C(iv)","next_time_hint":"Check ratios, not just differences, for this sequence.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Type the correct 5th term.","kind":"numeric","points":1,"hints":["Check ratios, not just differences, for this sequence.","Divide consecutive terms to find the multiplier, then apply it."],"strand":"C(iv)","answer":162,"tolerance":0},{"id":"b","label":"(b)","prompt":"Explain the student''s error in a few words.","kind":"text","points":1,"hints":["What did the student assume about how the sequence grows?","Name the growth type they assumed versus the actual one."],"strand":"C(iv)","accepted":["it is geometric not arithmetic","they treated it as arithmetic but it is geometric","the ratio is constant, not the difference"],"keywords":[["geometric","ratio","multiply"],["arithmetic","difference","adding"]],"minKeywordGroups":1}]}},{"n":19,"t":"assess_parts","p":"Use correct notation: a quadratic sequence begins 5, 12, 23, 38, … (first differences 7, 11, 15; second difference 4). Its nth term is $a_n = 2n^2 + n + 2$. Verify the formula gives the 4th term, then use it for the 10th.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use correct notation: a quadratic sequence begins 5, 12, 23, 38, … (first differences 7, 11, 15; second difference 4). Its nth term is "},{"type":"mathInline","attrs":{"latex":"a_n = 2n^2 + n + 2"}},{"type":"text","text":". Verify the formula gives the 4th term, then use it for the 10th."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Quadratic sequence","columns":["n","1","2","3","4"],"rows":[["aₙ","5","12","23","38"],["1st difference","—","7","11","15"]]}}}]},"e":"a₄ = 2(16) + 4 + 2 = 38 ✓ matches the sequence. a₁₀ = 2(100) + 10 + 2 = 212.\n\nHint for next time: Substitute n = 4 into the given formula.","m":2,"df":"hard","tp":"quadratic sequences","st":"quadratic notation check","cfg":{"source":"assess2-myp5b-criteria","question_number":19,"myp_criterion":"C","strand":"C(i)","next_time_hint":"Substitute n = 4 into the given formula.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate the value the formula gives for the 4th term.","kind":"numeric","points":1,"hints":["Substitute n = 4 into the given formula.","Square 4, double it, then add n and 2."],"strand":"C(i)","answer":38,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the 10th term.","kind":"numeric","points":1,"hints":["Substitute n = 10 the same way.","Square 10, double it, then add 10 and 2."],"strand":"C(i)","answer":212,"tolerance":0}]}},{"n":20,"t":"assess_parts","p":"Write a complete line of reasoning: the sequence 9, 13, 17, 21, … represents the cost ($) of a taxi ride for 1, 2, 3, 4, … kilometres (a flag-fall plus a per-km rate). State the per-km rate and the flag-fall (cost at 0 km).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write a complete line of reasoning: the sequence 9, 13, 17, 21, … represents the cost ("},{"type":"text","text":"$) of a taxi ride for 1, 2, 3, 4, … kilometres (a flag-fall plus a per-km rate). State the per-km rate and the flag-fall (cost at 0 km)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Taxi costs","xLabel":"Distance (km)","yLabel":"Cost ($)","xMin":0,"xMax":5,"yMin":0,"yMax":25,"points":[[1,9],[2,13],[3,17],[4,21]],"joinPoints":false}}}]},"e":"Differences are 4, so the rate is $4 per km. Working back: at 0 km the cost is 9 − 4 = $5 flag-fall. Rule: C = 4n + 5.\n\nHint for next time: The rate is the constant growth between points.","m":2.5,"df":"medium","tp":"arithmetic sequences","st":"reasoning from a graph","cfg":{"source":"assess2-myp5b-criteria","question_number":20,"myp_criterion":"C","strand":"C(iv)","next_time_hint":"The rate is the constant growth between points.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"State the rate per kilometre.","kind":"numeric","points":1,"hints":["The rate is the constant growth between points.","Subtract consecutive costs on the graph."],"strand":"C(iv)","answer":4,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"State the flag-fall (the cost when 0 km are travelled).","kind":"numeric","points":1,"hints":["Extend the pattern one step backwards from 1 km.","Subtract the rate from the 1-km cost."],"strand":"C(iv)","answer":5,"tolerance":0,"unit":"$"},{"id":"c","label":"(c)","prompt":"Write the reasoning in one sentence: why is the flag-fall not $9?","kind":"text","points":0.5,"hints":["What does the $9 at 1 km already include?","Explain that the first kilometre''s cost includes both charges."],"strand":"C(iv)","accepted":["the $9 includes the first kilometre''s rate as well as the flag-fall","9 dollars includes 1 km at $4 plus flag-fall"],"keywords":[["includes","made up","contains"],["flag-fall","flag fall","first kilometre","rate"]],"minKeywordGroups":2}]}},{"n":21,"t":"assess_parts","p":"Maya starts a savings plan: she saves $25 in week 1 and increases her weekly saving by $5 every week. She is saving for a $600 bike.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Maya starts a savings plan: she saves "},{"type":"text","text":"$25 in week 1 and increases her weekly saving by $"},{"type":"text","text":"5 every week. She is saving for a "},{"type":"text","text":"$600 bike."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Maya''s savings plan","columns":["Week","1","2","3","4"],"rows":[["Saved ($)","25","30","35","40"]]}}}]},"e":"Week n saving = 25 + 5(n − 1) = 5n + 20. Week 10: $70. Total after 10 weeks = S₁₀ = (10/2)(25 + 70) = $475 — not yet $600.\n\nHint for next time: Compare consecutive weeks in the table.","m":3.0,"df":"medium","tp":"arithmetic sequences","st":"savings plan","cfg":{"source":"assess2-myp5b-criteria","question_number":21,"myp_criterion":"D","strand":"D(i)","next_time_hint":"Compare consecutive weeks in the table.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify Maya''s weekly increase.","kind":"numeric","points":0.5,"hints":["Compare consecutive weeks in the table.","Subtract one week''s saving from the next."],"strand":"D(i)","answer":5,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"Calculate how much she saves in week 10.","kind":"numeric","points":1,"hints":["Use an arithmetic nth term with a = 25, d = 5.","Start at 25 and add the increase 9 times."],"strand":"D(iii)","answer":70,"tolerance":0,"unit":"$"},{"id":"c","label":"(c)","prompt":"Calculate her total savings after 10 weeks.","kind":"numeric","points":1,"hints":["A total of an arithmetic sequence is a series sum.","Apply Sₙ = (n/2)(first + last) using week 1 and week 10."],"strand":"D(iii)","answer":475,"tolerance":0,"unit":"$"},{"id":"d","label":"(d)","prompt":"State whether she can buy the $600 bike after 10 weeks: type yes or no.","kind":"text","points":0.5,"hints":["Compare her total with the price of the bike.","Check your total from (c) against $600."],"strand":"D(v)","accepted":["no"],"keywords":[["no"]],"minKeywordGroups":1}]}},{"n":22,"t":"assess_parts","p":"A bacteria culture starts with 300 bacteria and doubles every hour. A microscope count is needed after 6 hours, when the culture is expected to cover a slide.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bacteria culture starts with 300 bacteria and doubles every hour. A microscope count is needed after 6 hours, when the culture is expected to cover a slide."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Bacteria growth","columns":["Hours","0","1","2","3"],"rows":[["Bacteria","300","600","1200","2400"]]}}}]},"e":"After 6 hours: 300 × 2⁶ = 300 × 64 = 19200. After 4 hours it was 300 × 2⁴ = 4800. The model assumes unlimited food and space, so it overestimates later growth.\n\nHint for next time: Compare consecutive counts.","m":3.0,"df":"hard","tp":"geometric sequences","st":"bacteria growth","cfg":{"source":"assess2-myp5b-criteria","question_number":22,"myp_criterion":"D","strand":"D(ii)","next_time_hint":"Compare consecutive counts.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify the hourly growth factor.","kind":"numeric","points":0.5,"hints":["Compare consecutive counts.","Divide one count by the previous count."],"strand":"D(i)","answer":2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the number of bacteria after 4 hours.","kind":"numeric","points":1,"hints":["Apply the growth factor 4 times to the start.","Multiply 300 by 2 to the power 4."],"strand":"D(iii)","answer":4800,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the number of bacteria after 6 hours.","kind":"numeric","points":1,"hints":["Continue the same doubling model.","Multiply 300 by 2 to the power 6."],"strand":"D(iii)","answer":19200,"tolerance":0},{"id":"d","label":"(d)","prompt":"Justify: state in a few words why the real count after many hours will be lower than the model predicts.","kind":"text","points":0.5,"hints":["What does the doubling model assume never runs out?","Think about food, space and waste in a real culture."],"strand":"D(iv)","accepted":["food and space run out","limited food and space slow growth"],"keywords":[["food","space","resources","limited","waste"]],"minKeywordGroups":1}]}},{"n":23,"t":"assess_parts","p":"A ball is dropped from 80 cm. Each bounce reaches half the previous height. Its total travel distance matters for a slow-motion camera setup.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ball is dropped from 80 cm. Each bounce reaches half the previous height. Its total travel distance matters for a slow-motion camera setup."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Bouncing ball heights","columns":["Bounce","1st peak","2nd peak","3rd peak","4th peak"],"rows":[["Height (cm)","40","20","10","?"]]}}}]},"e":"Bounce heights: 40, 20, 10, 5, … After the 4th bounce peak: 5 cm. Sum of first 4 bounce heights = 40 + 20 + 10 + 5 = 75 cm. Heights halve, so total distance stays below 80 + 2 × 80 = 240 cm — the model is a sensible approximation ignoring air resistance.\n\nHint for next time: Divide one height by the previous height.","m":3.0,"df":"hard","tp":"geometric series","st":"bouncing ball","cfg":{"source":"assess2-myp5b-criteria","question_number":23,"myp_criterion":"D","strand":"D(ii)","next_time_hint":"Divide one height by the previous height.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify the ratio between consecutive bounce heights.","kind":"numeric","points":0.5,"hints":["Divide one height by the previous height.","Compare 20 with 40."],"strand":"D(i)","answer":0.5,"tolerance":0.01},{"id":"b","label":"(b)","prompt":"Calculate the height of the 4th bounce peak.","kind":"numeric","points":1,"hints":["Keep applying the ratio.","Halve the 3rd peak height."],"strand":"D(iii)","answer":5,"tolerance":0,"unit":"cm"},{"id":"c","label":"(c)","prompt":"Calculate the sum of the first 4 bounce peak heights.","kind":"numeric","points":1,"hints":["Add the four peak heights, or use a geometric sum.","Add 40, 20, 10 and your (b) value."],"strand":"D(iii)","answer":75,"tolerance":0,"unit":"cm"},{"id":"d","label":"(d)","prompt":"State whether ''the ball bounces forever'' is sensible in reality: type yes or no.","kind":"text","points":0.5,"hints":["Real balls lose energy at each bounce.","Decide if endless bouncing matches the real context."],"strand":"D(v)","accepted":["no"],"keywords":[["no","energy","stops"]],"minKeywordGroups":1}]}},{"n":24,"t":"assess_parts","p":"A theatre has 15 seats in the front row, and each row behind has 3 more seats than the row in front. There are 12 rows. The manager needs the total capacity.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A theatre has 15 seats in the front row, and each row behind has 3 more seats than the row in front. There are 12 rows. The manager needs the total capacity."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Theatre seating","columns":["Row","1","2","3","4"],"rows":[["Seats","15","18","21","24"]]}}}]},"e":"Last row: 15 + 11 × 3 = 48 seats. Total capacity S₁₂ = (12/2)(15 + 48) = 378 seats.\n\nHint for next time: Compare consecutive rows.","m":2.5,"df":"medium","tp":"arithmetic series","st":"theatre capacity","cfg":{"source":"assess2-myp5b-criteria","question_number":24,"myp_criterion":"D","strand":"D(ii)","next_time_hint":"Compare consecutive rows.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify the increase in seats per row.","kind":"numeric","points":0.5,"hints":["Compare consecutive rows.","Subtract one row''s seats from the next."],"strand":"D(i)","answer":3,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the number of seats in the 12th row.","kind":"numeric","points":1,"hints":["Use the arithmetic nth-term formula.","Start at 15 and add the increase 11 times."],"strand":"D(iii)","answer":48,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the total capacity of the theatre.","kind":"numeric","points":0.5,"hints":["Sum the arithmetic series over 12 rows.","Use Sₙ = (n/2)(first + last)."],"strand":"D(iii)","answer":378,"tolerance":0},{"id":"d","label":"(d)","prompt":"The manager advertises ''about 380 seats''. State whether this is accurate: type yes or no.","kind":"text","points":0.5,"hints":["Compare the advertised number with your total.","Check how close 380 is to your capacity."],"strand":"D(iv)","accepted":["yes"],"keywords":[["yes","close","accurate"]],"minKeywordGroups":1}]}},{"n":25,"t":"assess_parts","p":"A car worth $24 000 depreciates by 15% each year (its value is multiplied by 0.85 annually). The owner plans when to sell it.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A car worth "},{"type":"text","text":"$24 000 depreciates by 15% each year (its value is multiplied by 0.85 annually). The owner plans when to sell it."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Car depreciation","columns":["Year","0","1","2"],"rows":[["Value ($)","24000","20400","17340"]]}}}]},"e":"After 1 year: 24000 × 0.85 = $20 400. After 3 years: 24000 × 0.85³ = $14 739 (to nearest dollar). The model gives a smooth estimate — real resale values vary with condition and market.\n\nHint for next time: Losing 15% leaves what percentage of the value?","m":3.0,"df":"hard","tp":"geometric sequences","st":"depreciation model","cfg":{"source":"assess2-myp5b-criteria","question_number":25,"myp_criterion":"D","strand":"D(ii)","next_time_hint":"Losing 15% leaves what percentage of the value?","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify the yearly multiplier for the car''s value.","kind":"numeric","points":0.5,"hints":["Losing 15% leaves what percentage of the value?","Write 100% − 15% as a decimal."],"strand":"D(i)","answer":0.85,"tolerance":0.005},{"id":"b","label":"(b)","prompt":"Calculate the value after 1 year.","kind":"numeric","points":1,"hints":["Apply the multiplier once.","Multiply the starting value by your multiplier."],"strand":"D(iii)","answer":20400,"tolerance":0,"unit":"$"},{"id":"c","label":"(c)","prompt":"Calculate the value after 3 years, to the nearest dollar.","kind":"numeric","points":1,"hints":["Apply the multiplier three times (a power).","Multiply the starting value by the multiplier cubed."],"strand":"D(iii)","answer":14739,"tolerance":1,"unit":"$"},{"id":"d","label":"(d)","prompt":"Justify the accuracy: state in a few words why the actual selling price may differ from the model.","kind":"text","points":0.5,"hints":["What real-world factors does a percentage model ignore?","Think about condition, mileage and the market."],"strand":"D(iv)","accepted":["condition and market vary","real prices depend on condition and demand"],"keywords":[["condition","market","mileage","demand","vary"]],"minKeywordGroups":1}]}}]'::jsonb) as x
on conflict (id) do nothing;

insert into question_options (id, question_id, label, is_correct, position)
select ('c5000000-0000-4000-8000' || lpad((300000 + (q.config->>'question_number')::int * 100 + (v.idx - 1))::text, 12, '0'))::uuid,
       q.id, v.variant, true, v.idx::int
  from questions q
  cross join lateral jsonb_array_elements_text(q.config->'accepted') with ordinality as v(variant, idx)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess2-myp5b-criteria'
on conflict (id) do nothing;

insert into quiz_questions (quiz_id, question_id, position, points)
select 'c5000000-0000-4000-8000-000000000001', q.id, (q.config->>'question_number')::int, q.points
  from questions q
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess2-myp5b-criteria'
on conflict (quiz_id, question_id) do nothing;

insert into exams (id, organization_id, quiz_id, class_id, title, description, instructions, duration_minutes, status, access_code, shared_link_enabled, settings, created_by)
values ('c5000000-0000-4000-8000-000000000002', '0a400000-0000-4000-8000-000000000001', 'c5000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000110', 'MYP5 (Grade 10) Formative Assessment 2 - Criteria A-D', 'Grade 10 · MYP 5 · Mathematics · Formative Assessment 2 (Criteria A–D). Explicit and recursive formulas, arithmetic, quadratic and geometric sequences, and series. Every answer is typed; hints are free and never give the answer.',
  'Type every answer in the box provided — there are no options to choose from. Each question shows its MYP criterion and strand. Multi-part questions have a separate box and separate marks for each part. Press the Hint button whenever you are stuck: hints show you the way but never give the answer, and using a hint costs no marks. You have 45 minutes. Your feedback shows the correct answer, a worked solution, a hint for next time, and your score by criterion A-D with an indicative MYP level band.',
  45, 'open', 'MYP5-FORM2-2026', true,
  '{"proctoring":false,"require_screen_share":false,"randomize_questions":false,"randomize_options":false,"pass_mark_percent":50,"results_published":true,"access_mode":"shared_link","identity_fields":[],"eligible_class_ids":["0a400000-0000-4000-8000-000000000110"],"attempt_policy":"single_resume","assessment_kind":"formative","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","total_marks":58.0,"source":"assess2-myp5b-criteria"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
on conflict (id) do nothing;

insert into question_hints (id, organization_id, exam_id, question_id, level, body, status, source, created_by, approved_by)
select ('c5000000-0000-4000-8000' || lpad((500000 + (q.config->>'question_number')::int * 10 + h.level)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', 'c5000000-0000-4000-8000-000000000002', q.id, h.level, h.body, 'published', 'manual', '3c3ed712-f409-4aa1-a645-816418e22ec4', '3c3ed712-f409-4aa1-a645-816418e22ec4'
  from questions q
  cross join lateral (values
    (1, case when q.type = 'assess_parts'
             then 'Work through the parts in order: later parts often build on earlier ones. Every part also has its own Hint button beside its answer box.'
             else q.config->'hints'->>0 end),
    (2, case when q.type = 'assess_parts'
             then 'For part (a), start here: ' || (q.config->'parts'->0->'hints'->>0)
             else q.config->'hints'->>1 end)
  ) as h(level, body)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess2-myp5b-criteria'
on conflict (id) do nothing;

commit;
